function Capacity({ label, active, capacity, color }: { label: string; active: number; capacity: number; color: 'amber' | 'teal' }) { const pct = capacity ? Math.round(active / capacity * 100) : 0; return <div><div className="flex justify-between text-sm"><span>{label}</span><span className="font-mono text-muted-foreground">{active}/{capacity}</span></div><div className="mt-3 h-2 rounded-full bg-muted"><div className={`h-2 rounded-full ${color === 'amber' ? 'bg-primary' : 'bg-secondary'}`} style={{ width: `${pct}%` }} /></div><p className="mt-2 font-mono text-[10px] text-muted-foreground">{pct}% in use</p></div>; }
function TransactionRow({ description, amount, direction, paymentMethod, createdAt }: { description: string; amount: number; direction: string; paymentMethod: string; createdAt: string }) { return <div className="flex items-center gap-3 border-b border-border py-3 last:border-0"><span className={`grid h-8 w-8 place-items-center rounded-full ${direction === 'income' ? 'bg-[#5cc7ac]/10 text-[#75d6bd]' : 'bg-destructive/10 text-destructive'}`}>{direction === 'income' ? <ArrowDownLeft size={14} /> : <ArrowUpRight size={14} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm">{description}</p><p className="font-mono text-[9px] uppercase text-muted-foreground">{paymentMethod} · {dateTime(createdAt)}</p></div><span className={`font-mono text-sm ${direction === 'income' ? 'text-[#75d6bd]' : 'text-destructive'}`}>{direction === 'income' ? '+' : '-'}{money(amount)}</span></div>; }
function ReadyRow({ session }: { session: ChargingSession }) { return <div className="mb-3 flex items-center gap-4 rounded-md border border-primary/20 bg-primary/5 p-4 last:mb-0"><div className="grid h-10 w-10 place-items-center rounded-md bg-primary/15 text-primary"><Smartphone size={19} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{session.customerName}</p><Status tone="good">Ready</Status></div><p className="mt-1 font-mono text-[10px] uppercase text-muted-foreground">{session.device.brand ?? session.device.type} · Bay {session.slotNumber} · {session.publicSessionId}</p></div><Link href="/admin/charging" className="grid h-9 w-9 place-items-center rounded-md border border-border text-muted-foreground hover:text-primary" data-testid={`link-ready-session-${session.id}`}><ChevronRight size={16} /></Link></div>; }

function Charging() {
  const q = useListChargingSessions({ query: { queryKey: getListChargingSessionsQueryKey() } });
  const qc = useQueryClient(); const update = useUpdateChargingStatus(); const collect = useCollectChargingSession();
  const [claim, setClaim] = useState<string | null>(null);
  const act = (id: string, status: 'charging' | 'ready' | 'cancelled') => update.mutate({ id, data: { status } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListChargingSessionsQueryKey() }) });
  return <><PageHead eyebrow="Service station" title="Charging floor" description="Move every device through its lifecycle with a clean handoff." action={<Link href="/admin/charging/new" className="inline-flex min-h-11 items-center justify-center gap-2 rounded-md bg-primary px-4 text-xs font-bold uppercase tracking-widest text-primary-foreground" data-testid="link-new-charging"><Plus size={16} /> Check in device</Link>} /><div className="mb-7 grid gap-4 sm:grid-cols-3"><CapacityCard label="Active sessions" value={q.data?.filter(s => !['collected', 'cancelled'].includes(s.status)).length ?? 0} icon={BatteryCharging} /><CapacityCard label="Ready for collection" value={q.data?.filter(s => s.status === 'ready').length ?? 0} icon={Check} accent="teal" /><CapacityCard label="Open bays" value={Math.max(0, 12 - (q.data?.filter(s => s.status !== 'collected').length ?? 0))} icon={Store} /></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Device / customer</th><th>Bay</th><th>Checked in</th><th>Status</th><th>Payment</th><th className="px-5">Action</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(s => <tr key={s.id} className="border-b border-border last:border-0 hover:bg-muted/20" data-testid={`row-charging-${s.id}`}><td className="px-5 py-4"><p className="font-semibold">{s.customerName}</p><p className="font-mono text-[10px] text-muted-foreground">{s.device.brand ?? s.device.type} {s.device.model ?? ''} · {s.publicSessionId}</p></td><td className="font-mono text-sm">B-{String(s.slotNumber).padStart(2, '0')}</td><td className="font-mono text-xs text-muted-foreground">{dateTime(s.timeIn)}</td><td><Status tone={s.status === 'ready' ? 'good' : s.status === 'cancelled' ? 'bad' : 'warn'}>{s.status}</Status></td><td><span className="font-mono text-sm">{money(s.amount)}</span><small className="ml-2 text-[10px] text-muted-foreground">{s.paymentStatus}</small></td><td className="px-5">{s.status === 'ready' ? <Button variant="teal" className="min-h-9 px-3 text-[10px]" onClick={() => setClaim(s.id)} data-testid={`button-collect-${s.id}`}><Check size={14} /> Collect</Button> : s.status === 'charging' ? <Button variant="ghost" className="min-h-9 px-3 text-[10px]" onClick={() => act(s.id, 'ready')} data-testid={`button-ready-${s.id}`}>Mark ready</Button> : <Button variant="ghost" className="min-h-9 px-3 text-[10px]" onClick={() => act(s.id, 'charging')} data-testid={`button-start-${s.id}`}>Start charge</Button>}</td></tr>)}</QueryState></tbody></table></div></Card>{claim && <Modal title="Release device" onClose={() => setClaim(null)}><p className="text-sm text-muted-foreground">Enter the customer claim code to complete this handoff.</p><input autoFocus className="mt-5 h-12 w-full rounded-md border border-input bg-muted/50 px-3 font-mono outline-none focus:border-primary" placeholder="Claim code" data-testid="input-claim-code" onChange={e => (e.currentTarget.dataset.value = e.target.value)} /><Button className="mt-5 w-full" onClick={() => { const value = document.querySelector<HTMLInputElement>('[data-testid="input-claim-code"]')?.value ?? ''; if (value.length < 8) return; collect.mutate({ id: claim, data: { claimId: value } }, { onSuccess: () => { setClaim(null); qc.invalidateQueries({ queryKey: getListChargingSessionsQueryKey() }); } }); }} disabled={collect.isPending} data-testid="button-confirm-collection">{collect.isPending ? 'Verifying…' : 'Verify and release'}</Button></Modal>}</>;
}
function CapacityCard({ label, value, icon: Icon, accent = 'amber' }: { label: string; value: number; icon: typeof BatteryCharging; accent?: 'amber' | 'teal' }) { return <Card className="p-5"><div className="flex justify-between"><p className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">{label}</p><Icon size={16} className={accent === 'teal' ? 'text-secondary' : 'text-primary'} /></div><p className="mt-5 font-mono text-3xl">{value}</p></Card>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-5"><div className="w-full max-w-md rounded-lg border border-border bg-card p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">{title}</h2><button onClick={onClose} className="rounded p-1 text-muted-foreground hover:bg-muted" data-testid="button-close-modal"><X size={18} /></button></div>{children}</div></div>; }

function ChargingNew() {
  const checkIn = useCheckInChargingSession(); const [, setLocation] = useLocation();
  const [form, setForm] = useState<Partial<ChargingCheckInInput>>({ deviceType: 'phone', expectedMinutes: 90, paymentMethod: 'cash', amount: 500 });
  const set = (key: string, value: string | number) => setForm(f => ({ ...f, [key]: value }));
  return <><PageHead eyebrow="New session" title="Check in a device" description="Capture the handoff cleanly. The system will assign the next available bay." /><Card className="max-w-3xl p-6 md:p-8"><div className="grid gap-5 md:grid-cols-2"><Field label="Customer name" value={form.customerName ?? ''} onChange={v => set('customerName', v)} test="input-customer-name" /><Field label="Phone number" value={form.phone ?? ''} onChange={v => set('phone', v)} test="input-phone" /><SelectField label="Device type" value={form.deviceType ?? 'phone'} onChange={v => set('deviceType', v)} options={['phone', 'laptop', 'tablet', 'powerbank', 'other']} test="select-device-type" /><Field label="Brand" value={form.brand ?? ''} onChange={v => set('brand', v)} test="input-brand" /><Field label="Model" value={form.model ?? ''} onChange={v => set('model', v)} test="input-model" /><Field label="Colour" value={form.color ?? ''} onChange={v => set('color', v)} test="input-color" /><Field label="Expected minutes" type="number" value={String(form.expectedMinutes ?? 90)} onChange={v => set('expectedMinutes', Number(v))} test="input-expected-minutes" /><Field label="Amount" type="number" value={String(form.amount ?? 500)} onChange={v => set('amount', Number(v))} test="input-amount" /><SelectField label="Payment method" value={form.paymentMethod ?? 'cash'} onChange={v => set('paymentMethod', v)} options={['cash', 'transfer', 'card', 'other']} test="select-payment-method" /></div><div className="mt-7 flex flex-col-reverse gap-3 border-t border-border pt-6 sm:flex-row sm:justify-end"><Button variant="ghost" onClick={() => setLocation('/admin/charging')} data-testid="button-cancel-checkin">Cancel</Button><Button disabled={checkIn.isPending || !form.customerName || !form.phone} onClick={() => checkIn.mutate({ data: form as ChargingCheckInInput }, { onSuccess: () => setLocation('/admin/charging') })} data-testid="button-submit-checkin"><BatteryCharging size={16} />{checkIn.isPending ? 'Checking in…' : 'Check in device'}</Button></div>{checkIn.isError && <p className="mt-4 text-sm text-destructive" data-testid="status-checkin-error">Check-in could not be completed. Review the details and try again.</p>}</Card></>;
}
function Field({ label, value, onChange, test, type = 'text' }: { label: string; value: string; onChange: (v: string) => void; test: string; type?: string }) { return <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{label}<input required type={type} value={value} onChange={e => onChange(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm text-foreground outline-none focus:border-primary" data-testid={test} /></label>; }
function SelectField({ label, value, onChange, options, test }: { label: string; value: string; onChange: (v: string) => void; options: string[]; test: string }) { return <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{label}<select value={value} onChange={e => onChange(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm text-foreground outline-none focus:border-primary" data-testid={test}>{options.map(o => <option key={o} value={o}>{o.replace('-', ' ')}</option>)}</select></label>; }

function Workspace() {
  const q = useListWorkspaceBookings({ query: { queryKey: getListWorkspaceBookingsQueryKey() } }); const qc = useQueryClient(); const checkIn = useCheckInWorkspaceBooking(); const checkOut = useCheckOutWorkspaceBooking(); const register = useRegisterWorkspaceBooking(); const [show, setShow] = useState(false); const [form, setForm] = useState({ customerName: '', phone: '', amount: '1000', deviceType: 'laptop' });
  const mutateDone = () => qc.invalidateQueries({ queryKey: getListWorkspaceBookingsQueryKey() });
  return <><PageHead eyebrow="Shared desk floor" title="Workspace" description="A clear view of who is checked in, who is expected, and which desks are available." action={<Button onClick={() => setShow(true)} data-testid="button-new-booking"><Plus size={16} /> Register visitor</Button>} /><div className="mb-7 grid gap-4 sm:grid-cols-3"><CapacityCard label="Occupied now" value={q.data?.filter(b => b.status === 'checked-in').length ?? 0} icon={BriefcaseBusiness} accent="teal" /><CapacityCard label="Capacity" value={12} icon={Store} /><CapacityCard label="Available" value={Math.max(0, 12 - (q.data?.filter(b => b.status === 'checked-in').length ?? 0))} icon={Check} /></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Visitor</th><th>Device</th><th>Time in</th><th>Status</th><th className="px-5">Action</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(b => <tr key={b.id} className="border-b border-border last:border-0" data-testid={`row-workspace-${b.id}`}><td className="px-5 py-4"><p className="font-semibold">{b.customerName}</p><p className="font-mono text-[10px] text-muted-foreground">{b.phone ?? 'No phone'} · {money(b.amount)}</p></td><td className="font-mono text-xs text-muted-foreground">{b.deviceInfo?.type ?? '—'}</td><td className="font-mono text-xs text-muted-foreground">{dateTime(b.timeIn ?? b.createdAt)}</td><td><Status tone={b.status === 'checked-in' ? 'good' : b.status === 'cancelled' ? 'bad' : 'neutral'}>{b.status}</Status></td><td className="px-5">{b.status === 'registered' ? <Button className="min-h-9 px-3 text-[10px]" onClick={() => checkIn.mutate({ id: b.id }, { onSuccess: mutateDone })} data-testid={`button-workspace-checkin-${b.id}`}>Check in</Button> : b.status === 'checked-in' ? <Button variant="ghost" className="min-h-9 px-3 text-[10px]" onClick={() => checkOut.mutate({ id: b.id }, { onSuccess: mutateDone })} data-testid={`button-workspace-checkout-${b.id}`}>Check out</Button> : <span className="text-xs text-muted-foreground">Complete</span>}</td></tr>)}</QueryState></tbody></table></div></Card>{show && <Modal title="Register visitor" onClose={() => setShow(false)}><div className="space-y-4 pt-5"><Field label="Customer name" value={form.customerName} onChange={v => setForm({ ...form, customerName: v })} test="input-workspace-name" /><Field label="Phone number" value={form.phone} onChange={v => setForm({ ...form, phone: v })} test="input-workspace-phone" /><Field label="Amount" type="number" value={form.amount} onChange={v => setForm({ ...form, amount: v })} test="input-workspace-amount" /><SelectField label="Device" value={form.deviceType} onChange={v => setForm({ ...form, deviceType: v })} options={['laptop', 'phone', 'tablet', 'other']} test="select-workspace-device" /><Button className="w-full" disabled={register.isPending || !form.customerName || !form.phone} onClick={() => register.mutate({ data: { customerName: form.customerName, phone: form.phone, amount: Number(form.amount), deviceInfo: { type: form.deviceType } } }, { onSuccess: () => { setShow(false); mutateDone(); } })} data-testid="button-submit-workspace">{register.isPending ? 'Registering…' : 'Register visitor'}</Button></div></Modal>}</>;
}

function Inventory() {
  const [search, setSearch] = useState(''); const q = useListProducts(search ? { search } : undefined, { query: { queryKey: getListProductsQueryKey(search ? { search } : undefined) } }); const create = useCreateProduct(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ sku: '', name: '', category: 'accessories', costPrice: '0', sellingPrice: '0', quantityOnHand: '0', reorderThreshold: '3' });
  return <><PageHead eyebrow="Stock control" title="Inventory" description="Know what is on the shelf before the next sale." action={<Button onClick={() => setShow(true)} data-testid="button-new-product"><Plus size={16} /> Add product</Button>} /><div className="mb-6 flex flex-col gap-3 sm:flex-row"><label className="relative max-w-md flex-1"><Search className="absolute left-3 top-3.5 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search SKU or product name" className="h-11 w-full rounded-md border border-input bg-card pl-10 pr-3 text-sm outline-none focus:border-primary" data-testid="input-search-products" /></label><Button variant="ghost" onClick={() => setSearch('')} data-testid="button-clear-product-search">Clear</Button></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Product</th><th>Category</th><th>Cost</th><th>Price</th><th>On hand</th><th className="px-5">State</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(p => <tr key={p.id} className="border-b border-border last:border-0" data-testid={`row-product-${p.id}`}><td className="px-5 py-4"><p className="font-semibold">{p.name}</p><p className="font-mono text-[10px] text-muted-foreground">{p.sku}</p></td><td className="text-sm text-muted-foreground">{p.category}</td><td className="font-mono text-sm">{money(p.costPrice)}</td><td className="font-mono text-sm">{money(p.sellingPrice)}</td><td className={`font-mono text-sm ${p.quantityOnHand <= p.reorderThreshold ? 'text-primary' : ''}`}>{p.quantityOnHand}</td><td className="px-5">{p.quantityOnHand <= p.reorderThreshold ? <Status tone="warn">Reorder</Status> : <Status tone="good">Healthy</Status>}</td></tr>)}</QueryState></tbody></table></div></Card>{show && <Modal title="Add product" onClose={() => setShow(false)}><div className="grid gap-4 pt-5 sm:grid-cols-2">{<Field label="SKU" value={form.sku} onChange={v => setForm({ ...form, sku: v })} test="input-product-sku" />}<Field label="Product name" value={form.name} onChange={v => setForm({ ...form, name: v })} test="input-product-name" /><Field label="Category" value={form.category} onChange={v => setForm({ ...form, category: v })} test="input-product-category" /><Field label="Cost price" type="number" value={form.costPrice} onChange={v => setForm({ ...form, costPrice: v })} test="input-product-cost" /><Field label="Selling price" type="number" value={form.sellingPrice} onChange={v => setForm({ ...form, sellingPrice: v })} test="input-product-price" /><Field label="Quantity on hand" type="number" value={form.quantityOnHand} onChange={v => setForm({ ...form, quantityOnHand: v })} test="input-product-quantity" /><Field label="Reorder threshold" type="number" value={form.reorderThreshold} onChange={v => setForm({ ...form, reorderThreshold: v })} test="input-product-threshold" /></div><Button className="mt-5 w-full" disabled={create.isPending || !form.sku || !form.name} onClick={() => create.mutate({ data: { ...form, costPrice: Number(form.costPrice), sellingPrice: Number(form.sellingPrice), quantityOnHand: Number(form.quantityOnHand), reorderThreshold: Number(form.reorderThreshold) } }, { onSuccess: () => { setShow(false); qc.invalidateQueries({ queryKey: getListProductsQueryKey() }); } })} data-testid="button-submit-product">{create.isPending ? 'Saving…' : 'Save product'}</Button></Modal>}</>;
}

function Sales() {
  const products = useListProducts(undefined, { query: { queryKey: getListProductsQueryKey() } }); const customers = useListCustomers(undefined, { query: { queryKey: getListCustomersQueryKey() } }); const sale = useCreateSale(); const qc = useQueryClient(); const [cart, setCart] = useState<Record<string, number>>({}); const [customerId, setCustomerId] = useState(''); const [paymentMethod, setPaymentMethod] = useState('cash'); const items = products.data?.filter(p => cart[p.id]) ?? []; const total = items.reduce((sum, p) => sum + p.sellingPrice * cart[p.id], 0);
  return <><PageHead eyebrow="Point of sale" title="Quick sale" description="Build a multi-item basket and close it in one clean handoff." /><div className="grid gap-7 xl:grid-cols-[1.2fr_.8fr]"><Card className="p-5"><SectionTitle>Available products</SectionTitle><QueryState loading={products.isLoading} error={products.isError} empty={!products.data?.length}><div className="grid gap-3 sm:grid-cols-2">{products.data?.filter(p => p.active && p.quantityOnHand > 0).map(p => <button key={p.id} onClick={() => setCart({ ...cart, [p.id]: (cart[p.id] ?? 0) + 1 })} className="flex min-h-20 items-center justify-between rounded-md border border-border bg-muted/20 p-4 text-left transition hover:border-primary hover:bg-primary/5" data-testid={`button-add-sale-${p.id}`}><div><p className="font-semibold">{p.name}</p><p className="font-mono text-[10px] text-muted-foreground">{p.quantityOnHand} available · {p.sku}</p></div><span className="font-mono text-sm text-primary">{money(p.sellingPrice)}</span></button>)}</div></QueryState></Card><Card className="p-5"><SectionTitle>Current basket</SectionTitle>{!items.length ? <div className="grid min-h-40 place-items-center rounded-md border border-dashed border-border text-center text-sm text-muted-foreground"><ShoppingCart className="mb-2" />Select a product to begin</div> : <div className="space-y-3">{items.map(p => <div key={p.id} className="flex items-center gap-3 border-b border-border pb-3"><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{p.name}</p><p className="font-mono text-[10px] text-muted-foreground">{cart[p.id]} × {money(p.sellingPrice)}</p></div><span className="font-mono text-sm">{money(p.sellingPrice * cart[p.id])}</span><button onClick={() => { const next = { ...cart }; delete next[p.id]; setCart(next); }} className="text-muted-foreground hover:text-destructive" data-testid={`button-remove-sale-${p.id}`}><X size={15} /></button></div>)}<div className="border-t border-border pt-4"><label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Customer (optional)<select value={customerId} onChange={e => setCustomerId(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm" data-testid="select-sale-customer"><option value="">Walk-in customer</option>{customers.data?.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="mt-4 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Payment<select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm" data-testid="select-sale-payment"><option value="cash">Cash</option><option value="transfer">Transfer</option><option value="card">Card</option><option value="other">Other</option></select></label><div className="mt-5 flex items-end justify-between"><span className="text-sm text-muted-foreground">Total</span><span className="font-mono text-2xl text-primary">{money(total)}</span></div><Button className="mt-5 w-full" disabled={sale.isPending} onClick={() => sale.mutate({ data: { customerId: customerId || undefined, items: items.map(p => ({ productId: p.id, quantity: cart[p.id] })), paymentMethod } as SaleInput }, { onSuccess: () => { setCart({}); qc.invalidateQueries({ queryKey: getListProductsQueryKey() }); qc.invalidateQueries({ queryKey: getListSalesQueryKey() }); } })} data-testid="button-complete-sale"><CreditCard size={16} />{sale.isPending ? 'Processing…' : 'Complete sale'}</Button></div></div>}</Card></div></>;
}

function Customers() {
  const [search, setSearch] = useState(''); const q = useListCustomers(search ? { search } : undefined, { query: { queryKey: getListCustomersQueryKey(search ? { search } : undefined) } }); const create = useCreateCustomer(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ name: '', phone: '', email: '' });
  return <><PageHead eyebrow="Customer register" title="Customers" description="Keep the customer record useful, current, and easy to find." action={<Button onClick={() => setShow(true)} data-testid="button-new-customer"><Plus size={16} /> Add customer</Button>} /><div className="mb-6 max-w-md"><label className="relative block"><Search className="absolute left-3 top-3.5 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by name or phone" className="h-11 w-full rounded-md border border-input bg-card pl-10 pr-3 text-sm outline-none focus:border-primary" data-testid="input-search-customers" /></label></div><Card className="overflow-hidden"><div className="divide-y divide-border"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(c => <div key={c.id} className="flex items-center gap-4 p-5" data-testid={`row-customer-${c.id}`}><span className="grid h-10 w-10 place-items-center rounded-full bg-secondary/20 font-mono text-sm text-secondary-foreground">{c.name.split(' ').map(x => x[0]).slice(0, 2).join('')}</span><div className="min-w-0 flex-1"><p className="font-semibold">{c.name}</p><p className="font-mono text-[10px] text-muted-foreground">{c.phone ?? 'No phone'} {c.email ? `· ${c.email}` : ''}</p></div><Status tone={c.whatsappOptIn ? 'good' : 'neutral'}>{c.whatsappOptIn ? 'WhatsApp on' : 'No WhatsApp'}</Status></div>)}</QueryState></div></Card>{show && <Modal title="Add customer" onClose={() => setShow(false)}><div className="space-y-4 pt-5"><Field label="Full name" value={form.name} onChange={v => setForm({ ...form, name: v })} test="input-customer-full-name" /><Field label="Phone number" value={form.phone} onChange={v => setForm({ ...form, phone: v })} test="input-customer-phone" /><Field label="Email (optional)" value={form.email} onChange={v => setForm({ ...form, email: v })} test="input-customer-email" type="email" /><Button className="w-full" disabled={create.isPending || form.name.length < 2} onClick={() => create.mutate({ data: { name: form.name, phone: form.phone, email: form.email } }, { onSuccess: () => { setShow(false); setForm({ name: '', phone: '', email: '' }); qc.invalidateQueries({ queryKey: getListCustomersQueryKey() }); } })} data-testid="button-submit-customer">{create.isPending ? 'Saving…' : 'Save customer'}</Button></div></Modal>}</>;
}

function Transactions() { const q = useListTransactions({ period: 'month' }, { query: { queryKey: getListTransactionsQueryKey({ period: 'month' }) } }); return <><PageHead eyebrow="Bookkeeping" title="Transactions" description="A central ledger for every income and expense recorded through operations." action={<Button variant="ghost" onClick={() => window.print()} data-testid="button-print-ledger"><Printer size={15} /> Print ledger</Button>} /><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[750px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Description</th><th>Type</th><th>Method</th><th>Date</th><th className="px-5 text-right">Amount</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(t => <tr key={t.id} className="border-b border-border last:border-0" data-testid={`row-transaction-${t.id}`}><td className="px-5 py-4 text-sm">{t.description}</td><td><Status tone={t.direction === 'income' ? 'good' : 'bad'}>{t.direction}</Status></td><td className="text-xs text-muted-foreground">{t.paymentMethod}</td><td className="font-mono text-xs text-muted-foreground">{dateTime(t.createdAt)}</td><td className={`px-5 text-right font-mono ${t.direction === 'income' ? 'text-[#75d6bd]' : 'text-destructive'}`}>{t.direction === 'income' ? '+' : '-'}{money(t.amount)}</td></tr>)}</QueryState></tbody></table></div></Card></>; }
function Receipts() { const q = useListReceipts({ query: { queryKey: getListReceiptsQueryKey() } }); return <><PageHead eyebrow="Proof of service" title="Receipts" description="Reopen, print, and hand over a clear record of every service." action={<Button variant="ghost" onClick={() => window.print()} data-testid="button-print-receipts"><Printer size={15} /> Print list</Button>} /><Card className="overflow-hidden"><div className="divide-y divide-border"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(r => <div key={r.id} className="flex flex-wrap items-center gap-4 p-5" data-testid={`row-receipt-${r.id}`}><span className="grid h-10 w-10 place-items-center rounded-md bg-primary/10 text-primary"><ReceiptText size={18} /></span><div className="min-w-[180px] flex-1"><p className="font-mono text-sm">{r.receiptNumber}</p><p className="text-xs text-muted-foreground">{r.customerName ?? 'Walk-in'} · {r.type}</p></div><span className="font-mono text-sm">{money(r.total)}</span><span className="text-xs text-muted-foreground">{dateTime(r.generatedAt)}</span><Button variant="ghost" className="min-h-9 px-3 text-[10px]" onClick={() => window.print()} data-testid={`button-reopen-receipt-${r.id}`}><Printer size={14} /> Reopen</Button></div>)}</QueryState></div></Card></>; }
function HistoryPage() { const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const q = useListHistory({ date, type: 'all' }, { query: { queryKey: getListHistoryQueryKey({ date, type: 'all' }) } }); return <><PageHead eyebrow="Audit trail" title="Daily history" description="Review what moved through the floor, shift by shift." action={<input type="date" value={date} onChange={e => setDate(e.target.value)} className="h-11 rounded-md border border-input bg-card px-3 font-mono text-xs" data-testid="input-history-date" />} />{q.data && <div className="mb-6 grid gap-4 sm:grid-cols-4">{[['REVENUE', money(q.data.summary.revenue)], ['CHARGING', q.data.summary.chargingCount], ['WORKSPACE', q.data.summary.workspaceCount], ['SALES', q.data.summary.salesCount]].map(([l, v]) => <Card key={l as string} className="p-5"><p className="font-mono text-[10px] text-muted-foreground">{l as string}</p><p className="mt-3 font-mono text-2xl">{v as string | number}</p></Card>)}</div>}<Card className="p-5"><SectionTitle>Recorded transactions</SectionTitle><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.transactions.length}>{q.data?.transactions.map(t => <TransactionRow key={t.id} {...t} />)}</QueryState></Card></>; }

function CustomerHome({ page = 'home' }: { page?: 'home' | 'device' | 'receipts' | 'notifications' }) { const q = useListChargingSessions({ query: { queryKey: getListChargingSessionsQueryKey() } }); const [, setLocation] = useLocation(); const customerSessions = q.data ?? []; return <div className="min-h-[100dvh] bg-background"><header className="flex h-[72px] items-center justify-between border-b border-border px-5 md:px-10"><Brand /><div className="flex items-center gap-4"><span className="hidden font-mono text-[10px] uppercase tracking-widest text-muted-foreground sm:block">Customer portal</span><Link href="/" className="rounded-md p-2 text-muted-foreground" data-testid="link-customer-logout"><LogOut size={17} /></Link></div></header><main className="mx-auto max-w-4xl p-5 py-10 md:p-10"><div className="mb-8 flex flex-wrap gap-2 border-b border-border pb-3">{[['home', 'Status', '/customer'], ['device', 'My device', '/customer/device'], ['receipts', 'Receipts', '/customer/receipts'], ['notifications', 'Notifications', '/customer/notifications']].map(([key, label, href]) => <Link key={key} href={href} className={`rounded-md px-4 py-2 text-xs font-bold uppercase tracking-wider ${page === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`} data-testid={`link-customer-${key}`}>{label}</Link>)}</div>{page === 'home' && <><PageHead eyebrow="Your SANFAANI visit" title="Hello, welcome back." description="Your latest operational status, in one place." /><Card className="p-6"><div className="flex items-start gap-4"><span className="grid h-12 w-12 place-items-center rounded-md bg-secondary/20 text-secondary"><BatteryCharging /></span><div className="flex-1"><p className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Latest device status</p><h2 className="mt-2 text-2xl font-semibold">{customerSessions[0]?.status ?? 'No active session'}</h2><p className="mt-1 text-sm text-muted-foreground">{customerSessions[0] ? `${customerSessions[0].device.brand ?? customerSessions[0].device.type} · Bay ${customerSessions[0].slotNumber}` : 'Your current charging and workspace activity will appear here.'}</p></div><Status tone={customerSessions[0]?.status === 'ready' ? 'good' : 'neutral'}>{customerSessions[0]?.status ?? 'quiet'}</Status></div></Card></>}{page === 'device' && <><PageHead eyebrow="Device details" title="Your device" /><Card className="p-6"><QueryState loading={q.isLoading} error={q.isError} empty={!customerSessions.length}>{customerSessions.slice(0, 1).map(s => <div key={s.id} className="grid gap-5 sm:grid-cols-2"><Detail label="Claim reference" value={s.publicSessionId} /><Detail label="Device" value={`${s.device.brand ?? ''} ${s.device.model ?? s.device.type}`} /><Detail label="Bay" value={`B-${String(s.slotNumber).padStart(2, '0')}`} /><Detail label="Status" value={s.status} /><Detail label="Checked in" value={dateTime(s.timeIn)} /><Detail label="Estimated ready" value={dateTime(s.estimatedReadyAt)} /></div>)}</QueryState></Card></>}{page === 'receipts' && <CustomerReceipts />}{page === 'notifications' && <><PageHead eyebrow="Updates" title="Notifications" /><Card className="p-6"><div className="flex gap-4"><Bell className="text-primary" /><div><h2 className="font-semibold">You are up to date</h2><p className="mt-1 text-sm text-muted-foreground">Collection and workspace updates will appear here.</p></div></div></Card></>}</main></div>; }
function Detail({ label, value }: { label: string; value: string }) { return <div className="rounded-md bg-muted/40 p-4"><p className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-2 text-sm font-semibold">{value}</p></div>; }
function CustomerReceipts() { const q = useListReceipts({ query: { queryKey: getListReceiptsQueryKey() } }); return <><PageHead eyebrow="Proof of service" title="Your receipts" /><Card className="divide-y divide-border overflow-hidden"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(r => <div key={r.id} className="flex items-center gap-4 p-5"><ReceiptText className="text-primary" /><div className="flex-1"><p className="font-mono text-sm">{r.receiptNumber}</p><p className="text-xs text-muted-foreground">{r.type} · {dateTime(r.generatedAt)}</p></div><span className="font-mono">{money(r.total)}</span></div>)}</QueryState></Card></>; }

type ModuleMap = Record<string, () => Promise<Record<string, unknown>>>;

function _resolveComponent(
  mod: Record<string, unknown>,
  name: string,
): ComponentType | undefined {
  const fns = Object.values(mod).filter(
    (v) => typeof v === "function",
  ) as ComponentType[];
  return (
    (mod.default as ComponentType) ||
    (mod.Preview as ComponentType) ||
    (mod[name] as ComponentType) ||
    fns[fns.length - 1]
  );
}

function PreviewRenderer({
  componentPath,
  modules,
}: {
  componentPath: string;
  modules: ModuleMap;
}) {
  const [Component, setComponent] = useState<ComponentType | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    setComponent(null);
    setError(null);

    async function loadComponent(): Promise<void> {
      const key = `./components/mockups/${componentPath}.tsx`;
      const loader = modules[key];
      if (!loader) {
        setError(`No component found at ${componentPath}.tsx`);
        return;
      }

      try {
        const mod = await loader();
        if (cancelled) {
          return;
        }
        const name = componentPath.split("/").pop()!;
        const comp = _resolveComponent(mod, name);
        if (!comp) {
          setError(
            `No exported React component found in ${componentPath}.tsx\n\nMake sure the file has at least one exported function component.`,
          );
          return;
        }
        setComponent(() => comp);
      } catch (e) {
        if (cancelled) {
          return;
        }

        const message = e instanceof Error ? e.message : String(e);
        setError(`Failed to load preview.\n${message}`);
      }
    }

    void loadComponent();

    return () => {
      cancelled = true;
    };
  }, [componentPath, modules]);

  if (error) {
    return (
      <pre style={{ color: "red", padding: "2rem", fontFamily: "system-ui" }}>
        {error}
      </pre>
    );
  }

  if (!Component) return null;

  return <Component />;
}

function MockupSandbox({ params }: { params?: Record<string, string | undefined> }) {
  const previewPath = params?.path;

  if (previewPath) {
    return (
      <PreviewRenderer
        componentPath={previewPath}
        modules={discoveredModules}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-8">
      <div className="text-center max-w-md">
        <h1 className="text-2xl font-semibold text-gray-900 mb-3">
          Component Preview Server
        </h1>
        <p className="text-gray-500 mb-4">
          This server renders individual components for the workspace canvas.
        </p>
      </div>
    </div>
  );
}

function AppRoutes() {
  return <Switch><Route path="/" component={Landing} /><Route path="/sign-in/*?" component={() => <AuthPage />} /><Route path="/sign-up/*?" component={() => <AuthPage signUp />} /><Route path="/admin/dashboard" component={() => <AdminShell><Dashboard /></AdminShell>} /><Route path="/admin/charging/new" component={() => <AdminShell><ChargingNew /></AdminShell>} /><Route path="/admin/charging" component={() => <AdminShell><Charging /></AdminShell>} /><Route path="/admin/workspace" component={() => <AdminShell><Workspace /></AdminShell>} /><Route path="/admin/inventory" component={() => <AdminShell><Inventory /></AdminShell>} /><Route path="/admin/sales" component={() => <AdminShell><Sales /></AdminShell>} /><Route path="/admin/customers" component={() => <AdminShell><Customers /></AdminShell>} /><Route path="/admin/transactions" component={() => <AdminShell><Transactions /></AdminShell>} /><Route path="/admin/history" component={() => <AdminShell><HistoryPage /></AdminShell>} /><Route path="/admin/receipts" component={() => <AdminShell><Receipts /></AdminShell>} /><Route path="/customer" component={() => <CustomerHome />} /><Route path="/customer/device" component={() => <CustomerHome page="device" />} /><Route path="/customer/receipts" component={() => <CustomerHome page="receipts" />} /><Route path="/customer/notifications" component={() => <CustomerHome page="notifications" />} /><Route path="/preview/:path*" component={MockupSandbox} /><Route component={NotFound} /></Switch>;
}
function App() { return <QueryClientProvider client={queryClient}><Router base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><AppRoutes /></ErrorBoundary></Router></QueryClientProvider>; }
export default App;